    assert_eq!(candidate("unique words only", "completely different"), vec!['unique', 'words', 'only', 'completely', 'different']);
    assert_eq!(candidate("a b c d e", "f g h i j"), vec!['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j']);
    assert_eq!(candidate("overlap words here and there", "there and words"), vec!['overlap', 'here']);
    assert_eq!(candidate("single", ""), vec!['single']);
    assert_eq!(candidate("apple banana cherry", "banana cherry date"), vec!['apple', 'date']);
    assert_eq!(candidate("a b c d e f g", "h i j k l m n o p q r s t u v w x y z"), vec!['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']);
    assert_eq!(candidate("", "singleword"), vec!['singleword']);
    assert_eq!(candidate("uncommon word one", "uncommon word two"), vec!['one', 'two']);
    assert_eq!(candidate("single", "single single"), vec![]);
    assert_eq!(candidate("a b c d e f g h i j k l m n o p q r s t u v w x y z", "a b c"), vec!['d', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']);
    assert_eq!(candidate("repeated repeated repeated", "unique"), vec!['unique']);
    assert_eq!(candidate("a b c d e f g", "h i j k l m n"), vec!['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n']);
    assert_eq!(candidate("longer sentence with more words included", "included more words with longer sentence"), vec![]);
    assert_eq!(candidate("overlap many words here", "many words overlap"), vec!['here']);
    assert_eq!(candidate("singleword", "different"), vec!['singleword', 'different']);
    assert_eq!(candidate("multiple same words here and here", "here and"), vec!['multiple', 'same', 'words']);
    assert_eq!(candidate("python programming language", "programming language for python"), vec!['for']);
    assert_eq!(candidate("abc def ghi jkl mno", "pqr stu vwx yza"), vec!['abc', 'def', 'ghi', 'jkl', 'mno', 'pqr', 'stu', 'vwx', 'yza']);
    assert_eq!(candidate("single", "single unique"), vec!['unique']);
    assert_eq!(candidate("many different words in this sentence", "completely different words in this sentence"), vec!['many', 'completely']);
    assert_eq!(candidate("only one word", ""), vec!['only', 'one', 'word']);
    assert_eq!(candidate("singleword", ""), vec!['singleword']);
    assert_eq!(candidate("common words overlap", "overlap common words"), vec![]);
}
